    {
        if (coefficients.Length != 5)
        {
            throw new ArgumentException("The coefficients array must contain exactly five elements.");
        }

        Complex[] roots = new Complex[4];

        Complex a = coefficients[4];
        Complex b = coefficients[3];
        Complex c = coefficients[2];
        Complex d = coefficients[1];
        Complex e = coefficients[0];

        Complex p = (8 * a * c - 3 * b * b) / (8 * a * a);
        Complex q = (b * b * b - 4 * a * b * c + 8 * a * a * d) / (8 * a * a * a);
        Complex r = (-3 * b * b * b * b + 256 * a * a * a * e - 64 * a * a * b * d + 16 * a * b * b * c) / (256 * a * a * a * a);

        Complex discriminant = q * q - 4 * p * p * p - 4 * r * r * p + 18 * p * q * r - 27 * r * r * r;

        if (discriminant == Complex.Zero)
        {
            Complex discriminant0 = q * q - 4 * p * p * p;
            Complex discriminant1 = 18 * p * q * r - 27 * r * r * r;

            if (discriminant0 == Complex.Zero && discriminant1 == Complex.Zero)
            {
                // All roots are zero (repeated roots)
                roots[0] = roots[1] = roots[2] = roots[3] = Complex.Zero;
            }
            else if (discriminant0 == Complex.Zero)
            {
                // Two repeated roots and two zero roots
                roots[0] = roots[1] = -q / (4 * p);
                roots[2] = roots[3] = Complex.Zero;
            }
            else
            {
                // Two repeated roots and two zero roots
                roots[0] = roots[1] = (-q + Complex.Sqrt(discriminant1)) / (4 * p);
                roots[2] = roots[3] = (-q - Complex.Sqrt(discriminant1)) / (4 * p);
            }
        }
        else if (discriminant.Real > 0)
        {
            Complex sqrtDiscriminant = Complex.Sqrt(discriminant);

            Complex cubeRoot1 = (q + sqrtDiscriminant) / 2;
            Complex cubeRoot2 = (q - sqrtDiscriminant) / 2;

            Complex root1 = Complex.Pow(cubeRoot1, 1.0 / 3.0);
            Complex root2 = Complex.Pow(cubeRoot2, 1.0 / 3.0);

            roots[0] = -b / (4 * a) + root1 + root2;
            roots[1] = -b / (4 * a) - 0.5 * (root1 + root2) + Complex.ImaginaryOne * 0.5 * Complex.Sqrt(3) * (root1 - root2);
            roots[2] = -b / (4 * a) - 0.5 * (root1 + root2) - Complex.ImaginaryOne * 0.5 * Complex.Sqrt(3) * (root1 - root2);
            roots[3] = -b / (4 * a) - root1 - root2;
        }
        else if (discriminant.Real < 0)
        {
            Complex sqrtDiscriminant = Complex.Sqrt(-discriminant);
            Complex phi = 1.0 / 3.0 * Complex.Acos(-q / (2 * p) * Complex.Sqrt(-27 / p));

            roots[0] = -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos(phi / 3);
            roots[1] = -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos((phi + 2 * Math.PI) / 3);
            roots[2] = -b / (4 * a) + 2 * Complex.Sqrt(-p) * Complex.Cos((phi + 4 * Math.PI) / 3);
            roots[3] = -b / (4 * a);
        }

        return roots;
    }
}

public class Program
