    public static void Main(string[] args)
    {
        Complex[] coefficients = new Complex[]
        {
            new Complex(1, 0), // a
            new Complex(0, 2), // b
            new Complex(3, 0), // c
            new Complex(0, -4), // d
            new Complex(5, 0) // e
        };

